// The shape `src/worker.ts` relies on. Annotated on a const there, because after
// `opennextjs-cloudflare build` TypeScript resolves the real (untyped) JavaScript
// instead of the declaration below and would otherwise infer `any`.
type OpenNextWorker = {
  // A plain `Request` (not `ExportedHandler`'s `Request<unknown, IncomingRequestCfProperties>`);
  // `src/worker.ts` closes the gap with `satisfies ExportedHandler<CloudflareEnv>`.
  fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response>;
};

// The shape `src/rpc/local-payload` relies on, annotated on a const there for the
// same reason. OpenNext only reads `.url` and `.cf` off the synthesised request.
type OpenNextRequestContextRunner = <T>(request: Request, env: CloudflareEnv, ctx: ExecutionContext, handler: () => Promise<T>) => Promise<T>;

// `.open-next/*` is generated by `opennextjs-cloudflare build` and gitignored, so it
// is present for some typechecks and absent for others. A `@ts-expect-error` on the
// import is wrong in exactly one of those states, so the modules are declared here
// instead. The pattern form is required: an ambient declaration cannot name a
// relative path.
declare module '*/.open-next/worker.js' {
  const handler: OpenNextWorker;
  export default handler;

  type DurableObjectClass = typeof import('cloudflare:workers').DurableObject<CloudflareEnv>;

  export const BucketCachePurge: DurableObjectClass;
  export const DOQueueHandler: DurableObjectClass;
  export const DOShardedTagCache: DurableObjectClass;
}

declare module '*/.open-next/cloudflare/init.js' {
  export const runWithCloudflareRequestContext: OpenNextRequestContextRunner;
}
